def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    full_colors = {c for row in grid for c in set(row) if all(v == c for v in row)}
    for r, row in enumerate(grid):
        for c in full_colors:
            positions = [i for i, v in enumerate(row) if v == c]
            if 0 < len(positions) < w and positions == list(range(len(positions))):
                for i in range(len(positions), w):
                    out[r][i] = 1
                return out
    return out
